    25	    public String generateOccupancyReport(LocalDate date) {
    26	        List<Room> rooms = roomRepo.findAll();
    27	        StringBuilder csv = new StringBuilder();
    28	        csv.append("room,type,reservation,check_in,check_out\n");
    29	
    30	        int occupiedCount = 0;
    31	        for (Room room : rooms) {
    32	            var reservations = reservationRepo.findByDateAndRoom(date, room.number());
    33	            if (reservations.isEmpty()) {
    34	                continue;
    35	            }
    36	            for (Reservation res : reservations) {
    37	                csv.append(room.number()).append(",");
    38	                csv.append(room.type().name()).append(",");
    39	                csv.append(res.getId()).append(",");
    40	                csv.append(formatDate(res.getCheckIn())).append(",");
    41	                csv.append(formatDate(res.getCheckOut())).append("\n");
    42	                occupiedCount++;
    43	            }
    44	        }
    45	
    46	        csv.append("total,").append(occupiedCount).append("/").append(rooms.size());
    47	
    48	        return csv.toString();
    49	    }
    50	
    51	    public String generateRevenueReport(int year, int month) {
    52	        List<Reservation> reservations = reservationRepo.findByMonthAndStatus(year, month);
    53	        StringBuilder csv = new StringBuilder();
    54	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    55	
    56	        BigDecimal total = BigDecimal.ZERO;
    57	        for (Reservation res : reservations) {
    58	            BigDecimal amount = res.getAmountPaid();
    59	            if (res.getRefund() != null) {
    60	                amount = amount.subtract(res.getRefund());
    61	            }
    62	
    63	            csv.append(res.getId()).append(",");
    64	            csv.append(res.getRoomNumber()).append(",");
    65	            csv.append(formatDate(res.getCheckIn())).append(",");
    66	            csv.append(formatDate(res.getCheckOut())).append(",");
    67	            csv.append(res.getStatus().name()).append(",");
    68	            csv.append(formatCurrency(amount)).append("\n");
    69	
    70	            total = total.add(amount);
    71	        }
    72	
    73	        csv.append("total,,,,,").append(formatCurrency(total));
    74	
    75	        return csv.toString();
    76	    }
    77	
    78	    private String formatDate(LocalDate date) {
    79	        return date.toString();
    80	    }
    81	
    82	    private String formatCurrency(BigDecimal value) {
    83	        return String.format("%.2f", value).replace(",", ".");
    84	    }
    85	}
