    18	public class ReservationService {
    19	    private static final ReservationService instance = new ReservationService();
    20	    private final ReservationRepository reservationRepo = ReservationRepository.getInstance();
    21	    private final RoomRepository roomRepo = RoomRepository.getInstance();
    22	    private final MessageRepository messageRepo = MessageRepository.getInstance();
    23	
    24	    private ReservationService() {
    25	    }
    26	
    27	    public static ReservationService getInstance() {
    28	        return instance;
    29	    }
    30	
    31	    public Reservation createReservation(
    32	        int roomNumber,
    33	        String guestName,
    34	        String guestEmail,
    35	        String guestCpf,
    36	        String companyCnpj,
    37	        String companyName,
    38	        String guestPassport,
    39	        String guestCountry,
    40	        LocalDate checkIn,
    41	        LocalDate checkOut,
    42	        int guests,
    43	        RatePlan ratePlan
    44	    ) {
    45	        Room room = roomRepo.findByNumber(roomNumber)
    46	            .orElseThrow(() -> new IllegalArgumentException("Room not found"));
    47	
    48	        if (guests < 1 || guests > room.capacity()) {
    49	            throw new IllegalArgumentException("Invalid number of guests");
    50	        }
    51	
    52	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    53	            throw new IllegalArgumentException("Invalid dates");
    54	        }
    55	
    56	        var conflicts = reservationRepo.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
    57	        if (!conflicts.isEmpty()) {
    58	            throw new IllegalArgumentException("Room unavailable for those dates");
    59	        }
    60	
    61	        int nights = PriceCalculator.calculateNights(checkIn, checkOut);
    62	        BigDecimal subtotal = BigDecimal.ZERO;
    63	        for (int i = 0; i < nights; i++) {
    64	            LocalDate date = checkIn.plusDays(i);
    65	            BigDecimal nightPrice = PriceCalculator.calculateNightlyPrice(room.nightlyRate(), date);
    66	            subtotal = subtotal.add(nightPrice);
    67	        }
    68	
    69	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
    70	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    71	
    72	        Reservation reservation = new Reservation(
    73	            0,
    74	            roomNumber,
    75	            guestName,
    76	            guestEmail,
    77	            guestCpf,
    78	            companyCnpj,
    79	            companyName,
    80	            guestPassport,
    81	            guestCountry,
    82	            checkIn,
    83	            checkOut,
    84	            guests,
    85	            ratePlan,
    86	            nights,
    87	            subtotal,
    88	            discount,
    89	            total,
    90	            ReservationStatus.PENDING,
    91	            BigDecimal.ZERO,
    92	            null
    93	        );
    94	
    95	        return reservationRepo.save(reservation);
    96	    }
    97	
    98	    public Reservation getReservation(long id) {
    99	        return reservationRepo.findById(id)
   100	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
   101	    }
   102	
   103	    public Reservation confirmReservation(long id) {
   104	        Reservation reservation = getReservation(id);
   105	
   106	        if (reservation.getStatus() != ReservationStatus.PENDING) {
   107	            throw new IllegalArgumentException("Cannot confirm non-pending reservation");
   108	        }
   109	
   110	        reservation.setStatus(ReservationStatus.CONFIRMED);
   111	        reservation.setAmountPaid(reservation.getTotal());
   112	        reservationRepo.update(reservation);
   113	
   114	        sendConfirmationEmail(reservation);
   115	
   116	        return reservationRepo.findById(id).orElseThrow();
   117	    }
   118	
   119	    public Reservation checkIn(long id) {
   120	        Reservation reservation = getReservation(id);
   121	
   122	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   123	            throw new IllegalArgumentException("Cannot check in non-confirmed reservation");
   124	        }
   125	
   126	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   127	        reservationRepo.update(reservation);
   128	
   129	        return reservationRepo.findById(id).orElseThrow();
   130	    }
   131	
   132	    public Document checkOut(long id) {
   133	        Reservation reservation = getReservation(id);
   134	
   135	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   136	            throw new IllegalArgumentException("Cannot check out reservation that is not checked in");
   137	        }
   138	
   139	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   140	        reservationRepo.update(reservation);
   141	
   142	        Room room = roomRepo.findByNumber(reservation.getRoomNumber())
   143	            .orElseThrow(() -> new IllegalArgumentException("Room not found"));
   144	
   145	        return DocumentGeneratorFactory.create(reservation)
   146	            .generate(reservation, room);
   147	    }
   148	
   149	    public Reservation cancelReservation(long id) {
   150	        Reservation reservation = getReservation(id);
   151	
   152	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   153	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   154	            throw new IllegalArgumentException("Cannot cancel reservation in current status");
   155	        }
   156	
   157	        ReservationStatus previousStatus = reservation.getStatus();
   158	        reservation.setStatus(ReservationStatus.CANCELLED);
   159	
   160	        if (previousStatus == ReservationStatus.CONFIRMED) {
   161	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
   162	                reservation.setRefund(reservation.getAmountPaid());
   163	            } else {
   164	                reservation.setRefund(BigDecimal.ZERO);
   165	            }
   166	        }
   167	
   168	        reservationRepo.update(reservation);
   169	
   170	        return reservationRepo.findById(id).orElseThrow();
   171	    }
   172	
   173	    public Document getDocument(long id) {
   174	        Reservation reservation = getReservation(id);
   175	
   176	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
   177	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
   178	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
   179	            throw new IllegalArgumentException("Document not available for this reservation");
   180	        }
   181	
   182	        Room room = roomRepo.findByNumber(reservation.getRoomNumber())
   183	            .orElseThrow(() -> new IllegalArgumentException("Room not found"));
   184	
   185	        return DocumentGeneratorFactory.create(reservation)
   186	            .generate(reservation, room);
   187	    }
   188	
   189	    private void sendConfirmationEmail(Reservation reservation) {
   190	        Room room = roomRepo.findByNumber(reservation.getRoomNumber())
   191	            .orElseThrow(() -> new IllegalArgumentException("Room not found"));
   192	
   193	        Document document = DocumentGeneratorFactory.create(reservation)
   194	            .generate(reservation, room);
   195	
   196	        String body = "Olá, " + reservation.getGuestName() + "!\n\n" +
   197	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   198	            document.text() + "\n\n" +
   199	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   200	            "Até breve!";
   201	
   202	        messageRepo.save("EMAIL", reservation.getGuestEmail(),
   203	            "Reserva confirmada - Pousada Maré Alta", body);
   204	    }
   205	}
