     1	package com.pousada.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.format.DateTimeFormatter;
     6	import java.util.Locale;
     7	
     8	public class Formatter {
     9	    private static final DateTimeFormatter BR_DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    10	    private static final DateTimeFormatter ISO_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    11	    private static final DateTimeFormatter EN_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    12	    private static final Locale BR_LOCALE = new Locale("pt", "BR");
    13	
    14	    public static String formatBrDate(LocalDate date) {
    15	        return date.format(BR_DATE_FORMAT);
    16	    }
    17	
    18	    public static String formatIsoDate(LocalDate date) {
    19	        return date.format(ISO_DATE_FORMAT);
    20	    }
    21	
    22	    public static String formatEnDate(LocalDate date) {
    23	        return date.format(EN_DATE_FORMAT);
    24	    }
    25	
    26	    public static String formatBrCurrency(BigDecimal value) {
    27	        String formatted = String.format(Locale.US, "%.2f", value);
    28	        String[] parts = formatted.split("\\.");
    29	        String intPart = parts[0];
    30	        String decPart = parts[1];
    31	        StringBuilder result = new StringBuilder();
    32	        int len = intPart.length();
    33	        for (int i = 0; i < len; i++) {
    34	            if (i > 0 && (len - i) % 3 == 0) {
    35	                result.append(".");
    36	            }
    37	            result.append(intPart.charAt(i));
    38	        }
    39	        return "R$ " + result.toString() + "," + decPart;
    40	    }
    41	
    42	    public static String formatEnCurrency(BigDecimal value) {
    43	        return String.format(Locale.US, "BRL %.2f", value).replace(",", ".");
    44	    }
    45	
    46	    public static String formatCpf(String cpf) {
    47	        if (cpf == null || cpf.isEmpty()) return "";
    48	        cpf = cpf.replaceAll("\\D", "");
    49	        if (cpf.length() != 11) return cpf;
    50	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    51	               cpf.substring(6, 9) + "-" + cpf.substring(9);
    52	    }
    53	
    54	    public static String formatCnpj(String cnpj) {
    55	        if (cnpj == null || cnpj.isEmpty()) return "";
    56	        cnpj = cnpj.replaceAll("\\D", "");
    57	        if (cnpj.length() != 14) return cnpj;
    58	        return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." +
    59	               cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12);
    60	    }
    61	}
