     1	package com.pousada.util;
     2	
     3	import com.pousada.domain.RatePlan;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	public class PriceCalculator {
    10	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    11	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    12	    private static final int SCALE = 2;
    13	    private static final RoundingMode ROUNDING = RoundingMode.HALF_EVEN;
    14	
    15	    public static boolean isHighSeason(LocalDate date) {
    16	        Month month = date.getMonth();
    17	        int dayOfMonth = date.getDayOfMonth();
    18	
    19	        if (month == Month.JULY) return true;
    20	        if (month == Month.DECEMBER) return true;
    21	        if (month == Month.JANUARY) return true;
    22	        if (month == Month.FEBRUARY && dayOfMonth <= 28) return true;
    23	
    24	        return false;
    25	    }
    26	
    27	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
    28	        if (isHighSeason(date)) {
    29	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
    30	                    .setScale(SCALE, ROUNDING);
    31	        }
    32	        return baseRate.setScale(SCALE, ROUNDING);
    33	    }
    34	
    35	    public static BigDecimal calculateSubtotal(BigDecimal nightlyPrice, int nights) {
    36	        return nightlyPrice.multiply(new BigDecimal(nights))
    37	                .setScale(SCALE, ROUNDING);
    38	    }
    39	
    40	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    41	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    42	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
    43	                    .setScale(SCALE, ROUNDING);
    44	        }
    45	        return BigDecimal.ZERO.setScale(SCALE, ROUNDING);
    46	    }
    47	
    48	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    49	        return subtotal.subtract(discount)
    50	                .setScale(SCALE, ROUNDING);
    51	    }
    52	
    53	    public static BigDecimal calculateIss(BigDecimal total) {
    54	        return total.multiply(new BigDecimal("0.05"))
    55	                .setScale(SCALE, ROUNDING);
    56	    }
    57	
    58	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    59	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    60	    }
    61	}

